type Snapshot = {
  readonly diag_history: readonly IRow[];
  readonly diag_seen: readonly IRow[];
  readonly diagnostic: readonly IRow[];
  readonly file_line: readonly IRow[];
  readonly ratchet: readonly IRow[];
  readonly tick_rel: readonly IRow[];
};

function read_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    diag_history: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "line", CASE WHEN json_valid("code") AND json_type("code") = 'object' AND json_type("code", '$.fn') = 'text' AND json_type("code", '$.args') = 'array' THEN json_extract("code", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("code", '$.args')), '') || ')' ELSE "code" END AS "code", "opened_at" FROM "__txt_diag_history" t`, rel_columns.diag_history!, rel_column_types.diag_history!),
    diag_seen: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "line", CASE WHEN json_valid("code") AND json_type("code") = 'object' AND json_type("code", '$.fn') = 'text' AND json_type("code", '$.args') = 'array' THEN json_extract("code", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("code", '$.args')), '') || ')' ELSE "code" END AS "code", "at" FROM "__txt_diag_seen" t`, rel_columns.diag_seen!, rel_column_types.diag_seen!),
    diagnostic: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "line", CASE WHEN json_valid("code") AND json_type("code") = 'object' AND json_type("code", '$.fn') = 'text' AND json_type("code", '$.args') = 'array' THEN json_extract("code", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("code", '$.args')), '') || ')' ELSE "code" END AS "code", CASE WHEN json_valid("col4") AND json_type("col4") = 'object' AND json_type("col4", '$.fn') = 'text' AND json_type("col4", '$.args') = 'array' THEN json_extract("col4", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("col4", '$.args')), '') || ')' ELSE "col4" END AS "col4" FROM "__txt_diagnostic" t`, rel_columns.diagnostic!, rel_column_types.diagnostic!),
    file_line: select_rows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' AND json_type("path", '$.fn') = 'text' AND json_type("path", '$.args') = 'array' THEN json_extract("path", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("path", '$.args')), '') || ')' ELSE "path" END AS "path", "line", CASE WHEN json_valid("code") AND json_type("code") = 'object' AND json_type("code", '$.fn') = 'text' AND json_type("code", '$.args') = 'array' THEN json_extract("code", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("code", '$.args')), '') || ')' ELSE "code" END AS "code" FROM "__txt_file_line" t`, rel_columns.file_line!, rel_column_types.file_line!),
    ratchet: select_rows(seam, `SELECT CASE WHEN json_valid("col1") AND json_type("col1") = 'object' AND json_type("col1", '$.fn') = 'text' AND json_type("col1", '$.args') = 'array' THEN json_extract("col1", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("col1", '$.args')), '') || ')' ELSE "col1" END AS "col1", "col2" FROM "__txt_ratchet" t`, rel_columns.ratchet!, rel_column_types.ratchet!),
    tick_rel: select_rows(seam, `SELECT "at" FROM "tick_rel" t`, rel_columns.tick_rel!, rel_column_types.tick_rel!),
  });
}

type Snapshots = { readonly decoded: Snapshot; readonly stored: Snapshot };

function read_stored_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    diag_history: select_rows(seam, `SELECT "path", "line", "code", "opened_at" FROM "diag_history"`, rel_columns.diag_history!, rel_column_types.diag_history!),
    diag_seen: select_rows(seam, `SELECT "path", "line", "code", "at" FROM "diag_seen"`, rel_columns.diag_seen!, rel_column_types.diag_seen!),
    diagnostic: select_rows(seam, `SELECT "path", "line", "code", "col4" FROM "diagnostic"`, rel_columns.diagnostic!, rel_column_types.diagnostic!),
    file_line: select_rows(seam, `SELECT "path", "line", "code" FROM "file_line"`, rel_columns.file_line!, rel_column_types.file_line!),
    ratchet: select_rows(seam, `SELECT "col1", "col2" FROM "ratchet"`, rel_columns.ratchet!, rel_column_types.ratchet!),
    tick_rel: select_rows(seam, `SELECT "at" FROM "tick_rel"`, rel_columns.tick_rel!, rel_column_types.tick_rel!),
  });
}

function read_snapshots(seam: ISqlSeam): Observable<Snapshots> {
  return forkJoin({ decoded: read_snapshot(seam), stored: read_stored_snapshot(seam) });
}

